/**
 * LogoSpinner - AuthHub branded loading spinner
 *
 * Uses the AuthHub logo with a gentle, intermittent spin animation.
 * More distinctive than generic spinners and reinforces brand identity.
 *
 * Design considerations:
 * - Intermittent spin (not continuous) is less dizzying and more elegant
 * - Respects prefers-reduced-motion for accessibility
 * - Works in both light and dark mode
 */

export interface LogoSpinnerProps {
  /** Size variant: sm (16px), md (20px), lg (32px), xl (48px) */
  size?: 'sm' | 'md' | 'lg' | 'xl';
  /** Additional CSS classes */
  className?: string;
  /** Screen reader text for loading state */
  loadingText?: string;
}

const sizeClasses: Record<NonNullable<LogoSpinnerProps['size']>, string> = {
  sm: 'h-4 w-4',
  md: 'h-5 w-5',
  lg: 'h-8 w-8',
  xl: 'h-12 w-12',
};

const sizePixels: Record<NonNullable<LogoSpinnerProps['size']>, number> = {
  sm: 16,
  md: 20,
  lg: 32,
  xl: 48,
};

export function LogoSpinner({
  size = 'md',
  className,
  loadingText = 'Loading...',
}: LogoSpinnerProps) {
  const pixelSize = sizePixels[size];

  return (
    <span
      data-testid="logo-spinner"
      role="status"
      aria-label="Loading"
      className={cn(
        'inline-flex items-center justify-center',
        'animate-gentle-spin motion-reduce:animate-none',
        className
      )}
    >
      <Image
        src="/authhub.png"
        alt="AuthHub logo"
        width={pixelSize}
        height={pixelSize}
        className={cn('object-contain', sizeClasses[size])}
        priority
      />
      <span className="sr-only">{loadingText}</span>
    </span>
  );
}

'use client';

import { useEffect } from 'react';
import { useAuth } from '@clerk/nextjs';
import { useAuthOrBypass } from '@/lib/dev-auth';
import { loadHelpScoutIdentity } from '@/lib/api/help-scout';

const HELPSCOUT_SCRIPT_SRC = 'https://beacon-v2.helpscout.net';
const HELPSCOUT_SCRIPT_SELECTOR = 'script[data-helpscout-beacon="true"]';

type BeaconCall = {
  method: string;
  options?: unknown;
  data?: unknown;
};

type BeaconFunction = {
  (method: string, options?: unknown, data?: unknown): void;
  readyQueue?: BeaconCall[];
};

declare global {
  interface Window {
    Beacon?: BeaconFunction;
    __helpScoutBeaconInitialized?: boolean;
  }
}

function createBeaconStub(existingBeacon?: BeaconFunction): BeaconFunction {
  if (existingBeacon) {
    return existingBeacon;
  }

  const beaconStub: BeaconFunction = (method, options, data) => {
    beaconStub.readyQueue?.push({ method, options, data });
  };
  beaconStub.readyQueue = [];

  return beaconStub;
}

function ensureBeaconScript() {
  if (document.querySelector(HELPSCOUT_SCRIPT_SELECTOR)) {
    return;
  }

  const script = document.createElement('script');
  script.type = 'text/javascript';
  script.async = true;
  script.src = HELPSCOUT_SCRIPT_SRC;
  script.dataset.helpscoutBeacon = 'true';
  document.head.appendChild(script);
}

function getHelpScoutBeaconId(): string | null {
  return process.env.NEXT_PUBLIC_HELPSCOUT_BEACON_ID?.trim() || null;
}

export function HelpScoutBeacon() {
  const clerkAuth = useAuth();
  const { userId, isLoaded, isDevelopmentBypass } = useAuthOrBypass(clerkAuth);

  useEffect(() => {
    const beaconId = getHelpScoutBeaconId();
    if (!beaconId) {
      return;
    }

    if (isDevelopmentBypass) {
      return;
    }

    if (window.__helpScoutBeaconInitialized) {
      return;
    }

    window.Beacon = createBeaconStub(window.Beacon);
    ensureBeaconScript();
    window.Beacon('init', beaconId);
    window.__helpScoutBeaconInitialized = true;
  }, [isDevelopmentBypass]);

  useEffect(() => {
    if (!getHelpScoutBeaconId()) {
      return;
    }

    if (!isLoaded || !userId || isDevelopmentBypass) {
      return;
    }

    let cancelled = false;

    const identifyUser = async () => {
      try {
        const identity = await loadHelpScoutIdentity({
          getToken: clerkAuth.getToken,
        });

        if (cancelled) {
          return;
        }

        window.Beacon?.('identify', identity);
      } catch {
        // Keep Beacon available even when secure-mode identity lookup fails.
      }
    };

    void identifyUser();

    return () => {
      cancelled = true;
      window.Beacon?.('logout');
    };
  }, [clerkAuth, isDevelopmentBypass, isLoaded, userId]);

  return null;
}

