import { resolveApiUrl } from './api-env';

const AUTHORIZED_API_TIMEOUT_MS = 15_000;

export interface ApiErrorPayload {
  code: string;
  message: string;
  details?: any;
}

export class AuthorizedApiError extends Error {
  code: string;
  status: number;
  details?: any;

  constructor({ code, message, status, details }: { code: string; message: string; status: number; details?: any }) {
    super(message);
    this.name = 'AuthorizedApiError';
    this.code = code;
    this.status = status;
    this.details = details;
  }
}

interface AuthorizedApiFetchOptions extends Omit<RequestInit, 'headers'> {
  getToken: () => Promise<string | null>;
  headers?: HeadersInit;
  allowMissingToken?: boolean;
  onResponse?: (response: Response) => void;
}

export async function authorizedApiFetch<TResponse = any>(
  endpoint: string,
  options: AuthorizedApiFetchOptions
): Promise<TResponse> {
  const { getToken, headers, method = 'GET', signal: callerSignal, allowMissingToken = false, onResponse, ...rest } = options;

  const controller = new AbortController();
  const timeoutError = new AuthorizedApiError({
    code: 'TIMEOUT',
    message: 'Request timed out. Please try again.',
    status: 408,
  });
  let timeoutId: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timeoutId = setTimeout(() => {
      reject(timeoutError);
      controller.abort();
    }, AUTHORIZED_API_TIMEOUT_MS);
  });
  let rejectCallerAbort!: (reason: DOMException) => void;
  const callerAbort = new Promise<never>((_, reject) => { rejectCallerAbort = reject; });
  const abortFromCaller = () => {
    controller.abort();
    rejectCallerAbort(new DOMException('Aborted', 'AbortError'));
  };
  callerSignal?.addEventListener('abort', abortFromCaller, { once: true });
  if (callerSignal?.aborted) abortFromCaller();

  try {
    const token = await Promise.race([getToken(), timeout, callerAbort]);
    if (!token && !allowMissingToken) {
      throw new AuthorizedApiError({
        code: 'UNAUTHORIZED',
        message: 'Missing authentication token',
        status: 401,
      });
    }

    const requestHeaders = new Headers(headers);
    if (token) requestHeaders.set('Authorization', `Bearer ${token}`);
    if (!requestHeaders.has('Content-Type') && rest.body) {
      requestHeaders.set('Content-Type', 'application/json');
    }

    const response = await Promise.race([fetch(resolveApiUrl(endpoint), {
      ...rest,
      method,
      headers: requestHeaders,
      signal: controller.signal,
    }), timeout, callerAbort]);
    onResponse?.(response);

    let payload: any = null;
    try {
      payload = await Promise.race([response.json(), timeout, callerAbort]);
    } catch (error) {
      if (error === timeoutError || callerSignal?.aborted) throw error;
      payload = null;
    }

    const responseError = payload?.error;
    if (!response.ok || responseError) {
      throw new AuthorizedApiError({
        code: responseError?.code || 'REQUEST_FAILED',
        message: responseError?.message || `Request failed with status ${response.status}`,
        status: response.status,
        details: responseError?.details,
      });
    }

    return payload as TResponse;
  } finally {
    clearTimeout(timeoutId);
    callerSignal?.removeEventListener('abort', abortFromCaller);
  }
}

import { capturePosthogEvent } from '@/lib/analytics/capture-posthog';

type OAuthCallbackSuccessProps = {
  platform: string;
  auth_source: 'agency_redirect' | 'agency_meta_popup' | 'client_redirect' | 'client_meta_popup';
  agency_id?: string | null;
  connection_id?: string | null;
  requires_business_selection?: boolean;
};

type OAuthCallbackFailureProps = {
  platform: string | null;
  error_code: string;
  auth_source: 'agency_redirect' | 'agency_meta_popup' | 'client_redirect' | 'client_meta_popup';
  error_message?: string | null;
  agency_id?: string | null;
};

function normalizePlatform(platform: string | null | undefined): string {
  if (typeof platform === 'string' && platform.trim().length > 0) {
    return platform;
  }

  return 'unknown';
}

export function trackOAuthCallbackSuccess(properties: OAuthCallbackSuccessProps): void {
  const platform = normalizePlatform(properties.platform);
  void capturePosthogEvent('oauth_callback_success', {
    ...properties,
    platform,
  });
}

export function trackOAuthCallbackFailure(properties: OAuthCallbackFailureProps): void {
  const platform = properties.platform ? normalizePlatform(properties.platform) : 'unknown';
  const { error_message: _errorMessage, ...safeProperties } = properties;
  void capturePosthogEvent('oauth_callback_failure', {
    ...safeProperties,
    platform,
  });
}

export function trackClientOAuthExchangeSuccess(properties: {
  platform: string;
  connection_id: string;
  auth_source: 'client_redirect' | 'client_meta_popup';
}): void {
  trackOAuthCallbackSuccess({
    platform: properties.platform,
    auth_source: properties.auth_source,
    connection_id: properties.connection_id,
  });

  void capturePosthogEvent('client_oauth_exchange_success', {
    platform: normalizePlatform(properties.platform),
    connection_id: properties.connection_id,
    auth_source: properties.auth_source,
  });
}

export function trackClientOAuthExchangeFailure(properties: {
  platform?: string | null;
  error_code: string;
  error_message?: string | null;
  auth_source: 'client_redirect' | 'client_meta_popup';
}): void {
  trackOAuthCallbackFailure({
    platform: properties.platform ?? null,
    error_code: properties.error_code,
    auth_source: properties.auth_source,
  });

  void capturePosthogEvent('client_oauth_exchange_failure', {
    platform: properties.platform ? normalizePlatform(properties.platform) : 'unknown',
    error_code: properties.error_code,
    auth_source: properties.auth_source,
  });
}

